mapper.select:
select t.person_name,t.person_name personName,t.talk_time,t.talk_time talkTime,t.machine_id,t.machine_id
machineId,t.ccid,t.voice_path,t.voice_path voicePath,t.cl_id,t.cl_id clId,t.tel,t.person_id,t.person_id
personId,t.status_cd,t.status_cd statusCd,t.state,t.community_id,t.community_id
communityId,t.call_type,t.call_type callType,t.create_time createTime
from tel_call_log t
where 1 =1

    and t.person_name= #{personName}


    and t.talk_time= #{talkTime}


    and t.machine_id= #{machineId}


    and t.ccid= #{ccid}


    and t.voice_path= #{voicePath}


    and t.cl_id= #{clId}


    and t.tel= #{tel}


    and t.person_id= #{personId}


    and t.status_cd= #{statusCd}


    and t.state= #{state}


    and t.community_id= #{communityId}


    and t.call_type= #{callType}

order by t.create_time desc

    limit #{page}, #{row}

